PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE TABLE departments (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE soldiers (id TEXT PRIMARY KEY, personal_id TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, phone TEXT NOT NULL, department_id TEXT REFERENCES departments(id), approval_status TEXT NOT NULL DEFAULT 'pending' CHECK(approval_status IN ('pending','approved','archived')), approved_at INTEGER, archived_at INTEGER, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_soldiers_department ON soldiers(department_id);
CREATE INDEX idx_soldiers_status ON soldiers(approval_status);
CREATE TABLE equipment_items (id TEXT PRIMARY KEY, sku TEXT UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'יחידה', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE equipment_transactions (id TEXT PRIMARY KEY, soldier_id TEXT NOT NULL REFERENCES soldiers(id), type TEXT NOT NULL CHECK(type IN ('issue','return','adjustment')), status TEXT NOT NULL DEFAULT 'completed', actor_user_id TEXT REFERENCES users(id), note TEXT, created_at INTEGER NOT NULL);
CREATE TABLE equipment_transaction_lines (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES equipment_transactions(id) ON DELETE CASCADE, equipment_item_id TEXT NOT NULL REFERENCES equipment_items(id), quantity INTEGER NOT NULL CHECK(quantity > 0), condition TEXT NOT NULL DEFAULT 'good');
CREATE TABLE licenses (id TEXT PRIMARY KEY, soldier_id TEXT NOT NULL REFERENCES soldiers(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('civilian','military')), license_number TEXT, expires_at INTEGER, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(soldier_id,type));
CREATE TABLE shortage_reports (id TEXT PRIMARY KEY, soldier_id TEXT REFERENCES soldiers(id), reporter_name TEXT NOT NULL, phone TEXT, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')), resolved_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_shortages_status ON shortage_reports(status);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, safe_metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE INDEX idx_audit_entity ON audit_events(entity_type,entity_id,created_at);
